-- ---- POSTE PUR_OPX_JORF : Responsable Achats Opex site Jorf lasfar ----
IF NOT EXISTS (SELECT 1 FROM dbo.POSTE_DEFINITION WHERE POSTE = N'PUR_OPX_JORF')
