    INSERT INTO dbo.POSTE_DEFINITION (POSTE, INTITULE, INTITULE_COMPLET, OBSERVATIONS, DIMENSION, MISSION_PRINCIPALE, METIER, NIVEAU_ETUDE, TELETRAVAIL, PSH, INTER_INTERNE, INTER_EXTERNE, MANAGEMENT_DIRECTE, Management_indi, Expérience_globale, Expérience_spéci, Filière_Evolution, FERMETURE, DT_CREATION, CREATED_BY, MODIFIED_BY, CREATED_DATE, MODIFIED_DATE)
    VALUES (N'PUR_OPX_JORF', N'Responsable Achats Opex site Jorf lasfar', N'Responsable Achats Opex site Jorf lasfar', N'Piloter le processus d''acquisition des biens et services opérationnels (OPEX) pour le complexe industriel de Jorf Lasfar, en garantissant l''optimisation des coûts, la sécurisation des approvisionnements critiques et la conformité stricte aux procédures groupe dans un environnement industriel lourd.', NULL, N'<p>Définir et déployer la stratégie d&#x27;achats OPEX spécifique aux besoins du site de Jorf Lasfar en alignement avec la politique Groupe.</p><p>Piloter les appels d&#x27;offres complexes liés à l&#x27;exploitation du site, de la rédaction des cahiers des charges techniques à la sélection finale.</p><p>Mener les négociations commerciales et contractuelles pour maximiser les économies d&#x27;échelle et sécuriser la disponibilité des installations.</p><p>Assurer le suivi rigoureux de la performance des fournisseurs stratégiques intervenant sur le site via des revues de performance (OTIF/Qualité).</p><p>Garantir le respect du processus budgétaire achats du site et assurer le reporting précis des gains (savings) réalisés.</p><p>Coordonner étroitement les besoins avec les directions opérationnelles du site (Maintenance, Production, Logistique) pour optimiser les flux.</p><p>Veiller à la conformité contractuelle, à la sécurité des prestataires sur site et au respect des règles de contrôle interne.</p>', N'Ach', N'I', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Responsable Achats Groupe, Directeur Supply Chain Site, ou Category Manager Strategic Sourcing.', 0, GETDATE(), N'IMPORT_FDP', N'IMPORT_FDP', GETDATE(), GETDATE());
END;
