    INSERT INTO dbo.POSTE_DEFINITION (POSTE, INTITULE, INTITULE_COMPLET, OBSERVATIONS, DIMENSION, MISSION_PRINCIPALE, METIER, NIVEAU_ETUDE, TELETRAVAIL, PSH, INTER_INTERNE, INTER_EXTERNE, MANAGEMENT_DIRECTE, Management_indi, Expérience_globale, Expérience_spéci, Filière_Evolution, FERMETURE, DT_CREATION, CREATED_BY, MODIFIED_BY, CREATED_DATE, MODIFIED_DATE)
    VALUES (N'SAL_FIB_001', N'Sales Manager Fibre', N'Sales Manager Fibre', N'Piloter la stratégie de croissance et la performance commerciale de la gamme fibre d''acier en développant une prescription technique forte et des solutions à haute valeur ajoutée pour les grands projets d''infrastructure et industriels.', NULL, N'<p>Définir et exécuter le plan stratégique commercial pour la ligne de produits fibre d&#x27;acier sur les marchés cibles.</p><p>Assurer la prescription technique de la solution fibre d&#x27;acier auprès des bureaux d&#x27;études, architectes et maîtres d&#x27;ouvrage.</p><p>Négocier des contrats cadres et des partenariats stratégiques avec les grands comptes du BTP et de l&#x27;industrie.</p><p>Animer et coacher la force de vente spécialisée pour l&#x27;atteinte des objectifs de volume, de chiffre d&#x27;affaires et de marge.</p><p>Analyser les tendances du marché sidérurgique et la veille concurrentielle pour ajuster le positionnement tarifaire et l&#x27;offre.</p><p>Superviser la gestion du risque client, le suivi de la solvabilité et l&#x27;optimisation du DSO en collaboration avec la finance.</p><p>Piloter le cycle de vente via les outils CRM et assurer un reporting analytique de la performance à la direction générale.</p>', N'COM', N'I', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Directeur Commercial / Direction de Filiale', 0, GETDATE(), N'IMPORT_FDP', N'IMPORT_FDP', GETDATE(), GETDATE());
END;
