-- ---- POSTE CE_PFBP_DI_001 : Chef Exp chargé PF et By-Products Diplôme   UM6P - Diplôme d'ingénieur, man ----
IF NOT EXISTS (SELECT 1 FROM dbo.POSTE_DEFINITION WHERE POSTE = N'CE_PFBP_DI_001')
BEGIN
    INSERT INTO dbo.POSTE_DEFINITION (POSTE, INTITULE, INTITULE_COMPLET, OBSERVATIONS, DIMENSION, MISSION_PRINCIPALE, METIER, NIVEAU_ETUDE, TELETRAVAIL, PSH, INTER_INTERNE, INTER_EXTERNE, MANAGEMENT_DIRECTE, Management_indi, Expérience_globale, Expérience_spéci, Filière_Evolution, FERMETURE, DT_CREATION, CREATED_BY, MODIFIED_BY, CREATED_DATE, MODIFIED_DATE)
    VALUES (N'CE_PFBP_DI_001', N'Chef Exp chargé PF et By-Products Diplôme   UM6P - Diplôme d''ingénieur, man', N'Chef Exp chargé PF et By-Products Diplôme   UM6P - Diplôme d''ingénieur, man', N'Assurer la gestion opérationnelle et l''optimisation des flux de ferraille et des co-produits (by-products) pour garantir l''alimentation continue de l''aciérie tout en maximisant la valorisation des déchets industriels et en maîtrisant les coûts de manutention.', NULL, N'<p>Superviser la réception, le tri, la préparation et le stockage de la ferraille selon les standards de qualité et de sécurité.</p><p>Planifier et coordonner les chargements pour l&#x27;alimentation continue du Four à Arc Électrique (EAF).</p><p>Gérer le cycle de vie des co-produits (laitiers, poussières, calamines) depuis leur collecte jusqu&#x27;à leur valorisation ou évacuation.</p><p>Optimiser les flux logistiques internes au parc pour réduire les délais de rotation et les coûts de fonctionnement.</p><p>Assurer le suivi des indicateurs de performance (KPIs) liés à l&#x27;activité du parc et aux consommations de matières premières.</p><p>Garantir le respect strict des normes environnementales et des consignes de sécurité sur l&#x27;ensemble de la zone d&#x27;exploitation.</p><p>Manager les équipes de terrain (opérateurs, conducteurs d&#x27;engins) et coordonner l&#x27;activité des prestataires externes.</p><p>Proposer et mettre en œuvre des plans d&#x27;amélioration continue pour l&#x27;exploitation du parc.</p>', N'PRO', N'I', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Responsable de Production Aciérie ou Responsable Logistique Industrielle', 0, GETDATE(), N'IMPORT_FDP', N'IMPORT_FDP', GETDATE(), GETDATE());
END;
