-- ---- POSTE DO_JORF_001 : Directeur des Opérations des activités industrielles du Site de Jorf Lasfar ----
IF NOT EXISTS (SELECT 1 FROM dbo.POSTE_DEFINITION WHERE POSTE = N'DO_JORF_001')
BEGIN
    INSERT INTO dbo.POSTE_DEFINITION (POSTE, INTITULE, INTITULE_COMPLET, OBSERVATIONS, DIMENSION, MISSION_PRINCIPALE, METIER, NIVEAU_ETUDE, TELETRAVAIL, PSH, INTER_INTERNE, INTER_EXTERNE, MANAGEMENT_DIRECTE, Management_indi, Expérience_globale, Expérience_spéci, Filière_Evolution, FERMETURE, DT_CREATION, CREATED_BY, MODIFIED_BY, CREATED_DATE, MODIFIED_DATE)
    VALUES (N'DO_JORF_001', N'Directeur des Opérations des activités industrielles du Site de Jorf Lasfar', N'Directeur des Opérations des activités industrielles du Site de Jorf Lasfar', N'Piloter et coordonner l''ensemble des unités de production et de support technique du site de Jorf Lasfar pour garantir l''atteinte des objectifs de performance industrielle en termes de sécurité, de qualité, de coûts et de délais, tout en assurant la transformation digitale et l''amélioration continue des processus.', NULL, N'<p>Définir et piloter la stratégie opérationnelle du site en alignement avec la vision de la Direction Industrielle.</p><p>Garantir l&#x27;excellence opérationnelle de l&#x27;aciérie (EAF/CCM) et du train de laminage.</p><p>Superviser l&#x27;élaboration et le suivi du budget industriel du site et optimiser les coûts de production.</p><p>Assurer le respect strict des normes de sécurité, d&#x27;hygiène et d&#x27;environnement sur l&#x27;ensemble du site.</p><p>Piloter les projets de transformation digitale et d&#x27;automatisation des processus industriels.</p><p>Animer le dialogue social et coordonner le développement des compétences des équipes.</p><p>Garantir la fiabilité des équipements par une stratégie de maintenance préventive et prédictive performante.</p><p>Représenter la direction auprès des parties prenantes locales et assurer la conformité réglementaire.</p>', N'PRO', N'I', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Directeur de Site, Directeur Industriel Groupe, Directeur Technique.', 0, GETDATE(), N'IMPORT_FDP', N'IMPORT_FDP', GETDATE(), GETDATE());
END;
