    INSERT INTO dbo.POSTE_DEFINITION (POSTE, INTITULE, INTITULE_COMPLET, OBSERVATIONS, DIMENSION, MISSION_PRINCIPALE, METIER, NIVEAU_ETUDE, TELETRAVAIL, PSH, INTER_INTERNE, INTER_EXTERNE, MANAGEMENT_DIRECTE, Management_indi, Expérience_globale, Expérience_spéci, Filière_Evolution, FERMETURE, DT_CREATION, CREATED_BY, MODIFIED_BY, CREATED_DATE, MODIFIED_DATE)
    VALUES (N'IP_GE_DI_001', N'Ingénieur Projet', N'Ingénieur Projet', N'Concevoir, piloter et superviser la réalisation de projets d''installations électriques et d''automatisation industrielle pour garantir l''amélioration de la performance, de la fiabilité et de la sécurité des actifs de Sonasid.', NULL, N'<p>Réaliser les études de faisabilité technique et économique pour les nouveaux projets électriques.</p><p>Rédiger les cahiers des charges techniques (CCTP) et participer au processus de sélection des fournisseurs.</p><p>Superviser les travaux de montage et d&#x27;installation sur site en veillant au respect des normes de sécurité.</p><p>Assurer la programmation et la mise en service des automates et systèmes de contrôle-commande.</p><p>Coordonner les interventions avec les équipes de production et de maintenance pour minimiser les impacts sur l&#x27;exploitation.</p><p>Gérer le planning, le budget et le reporting d&#x27;avancement des projets sous sa responsabilité.</p><p>Veiller à la mise à jour de la documentation technique (schémas électriques, manuels) en fin de projet.</p><p>Assurer une veille technologique sur les solutions d&#x27;efficacité énergétique et de digitalisation.</p>', N'PRO', N'I', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Chef de Projet Senior, Responsable Travaux Neufs, Responsable Maintenance Électrique, Directeur Technique.', 0, GETDATE(), N'IMPORT_FDP', N'IMPORT_FDP', GETDATE(), GETDATE());
END;
