-- ---- POSTE MAINT_CAPEX_001 : Resp CAPEX et Fiabilité Mécanique ----
IF NOT EXISTS (SELECT 1 FROM dbo.POSTE_DEFINITION WHERE POSTE = N'MAINT_CAPEX_001')
BEGIN
    INSERT INTO dbo.POSTE_DEFINITION (POSTE, INTITULE, INTITULE_COMPLET, OBSERVATIONS, DIMENSION, MISSION_PRINCIPALE, METIER, NIVEAU_ETUDE, TELETRAVAIL, PSH, INTER_INTERNE, INTER_EXTERNE, MANAGEMENT_DIRECTE, Management_indi, Expérience_globale, Expérience_spéci, Filière_Evolution, FERMETURE, DT_CREATION, CREATED_BY, MODIFIED_BY, CREATED_DATE, MODIFIED_DATE)
    VALUES (N'MAINT_CAPEX_001', N'Resp CAPEX et Fiabilité Mécanique', N'Resp CAPEX et Fiabilité Mécanique', N'Piloter les projets d''investissement (CAPEX) mécaniques et garantir la fiabilité maximale des équipements de production en minimisant les arrêts non programmés par l''implémentation de stratégies de maintenance prédictive et d''analyse de performance.', NULL, N'<p>Élaborer et piloter le plan d&#x27;investissement (CAPEX) mécanique de l&#x27;usine depuis la conception jusqu&#x27;à la mise en service.</p><p>Définir et déployer la stratégie de fiabilité mécanique (plans de maintenance, analyses de criticité, études de vulnérabilité).</p><p>Piloter les analyses de causes racines (RCA) suite aux défaillances majeures et mettre en œuvre les plans d&#x27;actions correctifs.</p><p>Superviser l&#x27;implémentation et l&#x27;exploitation des outils de maintenance prédictive et d&#x27;analyse vibratoire.</p><p>Assurer une veille technologique pour moderniser les installations et optimiser le coût global de possession (TCO).</p><p>Gérer les budgets de maintenance et de projets en garantissant l&#x27;optimisation des coûts industriels.</p>', N'PRO', N'I', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Évolution possible vers un poste de Responsable Maintenance Site ou de Directeur Technique.', 0, GETDATE(), N'IMPORT_FDP', N'IMPORT_FDP', GETDATE(), GETDATE());
END;
