-- ---- POSTE MAINT_METH_001 : Responsable Bureau de Méthodes Site ----
IF NOT EXISTS (SELECT 1 FROM dbo.POSTE_DEFINITION WHERE POSTE = N'MAINT_METH_001')
BEGIN
    INSERT INTO dbo.POSTE_DEFINITION (POSTE, INTITULE, INTITULE_COMPLET, OBSERVATIONS, DIMENSION, MISSION_PRINCIPALE, METIER, NIVEAU_ETUDE, TELETRAVAIL, PSH, INTER_INTERNE, INTER_EXTERNE, MANAGEMENT_DIRECTE, Management_indi, Expérience_globale, Expérience_spéci, Filière_Evolution, FERMETURE, DT_CREATION, CREATED_BY, MODIFIED_BY, CREATED_DATE, MODIFIED_DATE)
    VALUES (N'MAINT_METH_001', N'Responsable Bureau de Méthodes Site', N'Responsable Bureau de Méthodes Site', N'Définir, optimiser et piloter la stratégie de maintenance du site afin de garantir la disponibilité et la fiabilité des équipements industriels au meilleur coût, tout en assurant le respect des standards de sécurité et de performance.', NULL, N'<p>Élaborer et piloter le plan de maintenance préventive et prédictive pour l&#x27;ensemble des équipements de l&#x27;usine.</p><p>Administrer et optimiser l&#x27;outil de GMAO (Gestion de la Maintenance Assistée par Ordinateur) pour assurer la traçabilité des interventions.</p><p>Réaliser des analyses de criticité et de fiabilité (méthodes AMDEC, RCM) pour identifier les points de défaillance majeurs.</p><p>Définir et gérer le stock de pièces de rechange critiques en collaboration avec les services Achats et Magasin.</p><p>Élaborer les modes opératoires et les procédures techniques de maintenance pour garantir la standardisation des pratiques.</p><p>Analyser les coûts de maintenance et proposer des plans d&#x27;optimisation budgétaire.</p><p>Assurer la veille technologique pour intégrer des solutions d&#x27;industrie 4.0 (IoT, maintenance prédictive).</p><p>Piloter les indicateurs de performance (KPIs) de la maintenance et animer les plans d&#x27;actions correctifs.</p>', N'PRO', N'I', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Évolution possible vers un poste de Directeur Maintenance, Directeur Technique ou Responsable Performance Industrielle.', 0, GETDATE(), N'IMPORT_FDP', N'IMPORT_FDP', GETDATE(), GETDATE());
END;
