    INSERT INTO dbo.POSTE_DEFINITION (POSTE, INTITULE, INTITULE_COMPLET, OBSERVATIONS, DIMENSION, MISSION_PRINCIPALE, METIER, NIVEAU_ETUDE, TELETRAVAIL, PSH, INTER_INTERNE, INTER_EXTERNE, MANAGEMENT_DIRECTE, Management_indi, Expérience_globale, Expérience_spéci, Filière_Evolution, FERMETURE, DT_CREATION, CREATED_BY, MODIFIED_BY, CREATED_DATE, MODIFIED_DATE)
    VALUES (N'SC_MAG_NAD_01', N'Responsable Magasin', N'Responsable Magasin', N'Piloter et optimiser l''ensemble des activités de réception, stockage, préparation et distribution des pièces de rechange et consommables industriels afin de garantir la disponibilité des ressources nécessaires à la maintenance et à la production, tout en assurant la fiabilité des stocks et le respect des normes de sécurité.', NULL, N'<p>Superviser les opérations de réception, de contrôle qualitatif et quantitatif des marchandises</p><p>Gérer l&#x27;organisation spatiale du magasin et optimiser les surfaces de stockage</p><p>Garantir la fiabilité des stocks par la mise en œuvre d&#x27;inventaires tournants et annuels</p><p>Piloter les flux de sorties et s&#x27;assurer du service aux clients internes (Maintenance et Production)</p><p>Veiller à l&#x27;application rigoureuse des procédures d&#x27;hygiène, sécurité et environnement (HSE) au sein du magasin</p><p>Analyser les indicateurs de performance du magasin et mettre en œuvre des plans de progrès</p><p>Coordonner avec le service Achats et Approvisionnements pour optimiser les niveaux de stock et éviter les ruptures ou le surstockage</p><p>Encadrer, former et évaluer l&#x27;équipe du magasin pour monter en compétence collectivement</p>', N'PRO', N'I', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Responsable Supply Chain Site, Responsable Logistique Régional ou Chef de Projet Excellence Opérationnelle.', 0, GETDATE(), N'IMPORT_FDP', N'IMPORT_FDP', GETDATE(), GETDATE());
END;
