-- ---- POSTE MAINT_MECA_NAD_001 : Responsable Maintenance Mécanique ----
IF NOT EXISTS (SELECT 1 FROM dbo.POSTE_DEFINITION WHERE POSTE = N'MAINT_MECA_NAD_001')
