    INSERT INTO dbo.POSTE_DEFINITION (POSTE, INTITULE, INTITULE_COMPLET, OBSERVATIONS, DIMENSION, MISSION_PRINCIPALE, METIER, NIVEAU_ETUDE, TELETRAVAIL, PSH, INTER_INTERNE, INTER_EXTERNE, MANAGEMENT_DIRECTE, Management_indi, Expérience_globale, Expérience_spéci, Filière_Evolution, FERMETURE, DT_CREATION, CREATED_BY, MODIFIED_BY, CREATED_DATE, MODIFIED_DATE)
    VALUES (N'MAINT_MECA_NAD_001', N'Responsable Maintenance Mécanique', N'Responsable Maintenance Mécanique', N'Piloter et optimiser la stratégie de maintenance mécanique de l''usine de Nador afin de garantir une disponibilité maximale des outils de production tout en maîtrisant les coûts et en assurant la sécurité des biens et des personnes.', NULL, N'<p>Élaborer et superviser le plan de maintenance préventive et prédictive pour l&#x27;ensemble du parc machines mécanique.</p><p>Coordonner les interventions curatives urgentes pour minimiser les temps d&#x27;arrêt de production (MTTR).</p><p>Piloter le budget annuel de maintenance mécanique et assurer le suivi des dépenses par rapport aux prévisions.</p><p>Manager et développer les compétences techniques et comportementales des équipes de maintenance mécanique.</p><p>Superviser les projets de modernisation, de revamping et les travaux neufs liés aux installations mécaniques.</p><p>Garantir le respect strict des normes de sécurité (HSE) et des procédures de travail lors de toutes les interventions de maintenance.</p><p>Optimiser la gestion du stock de pièces de rechange critiques en collaboration avec les services achats et magasin.</p><p>Analyser les défaillances récurrentes et mettre en place des actions d&#x27;amélioration continue pour augmenter le MTBF.</p>', N'PRO', N'I', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Chef de Département Maintenance Site, Responsable d''Exploitation, Directeur Technique.', 0, GETDATE(), N'IMPORT_FDP', N'IMPORT_FDP', GETDATE(), GETDATE());
END;
