-- ---- POSTE MNT_ELEC_NAD_001 : Responsable Maintenance électrique ----
IF NOT EXISTS (SELECT 1 FROM dbo.POSTE_DEFINITION WHERE POSTE = N'MNT_ELEC_NAD_001')
