-- ---- POSTE IND_EN_001 : Responsable Man ----
IF NOT EXISTS (SELECT 1 FROM dbo.POSTE_DEFINITION WHERE POSTE = N'IND_EN_001')
BEGIN
    INSERT INTO dbo.POSTE_DEFINITION (POSTE, INTITULE, INTITULE_COMPLET, OBSERVATIONS, DIMENSION, MISSION_PRINCIPALE, METIER, NIVEAU_ETUDE, TELETRAVAIL, PSH, INTER_INTERNE, INTER_EXTERNE, MANAGEMENT_DIRECTE, Management_indi, Expérience_globale, Expérience_spéci, Filière_Evolution, FERMETURE, DT_CREATION, CREATED_BY, MODIFIED_BY, CREATED_DATE, MODIFIED_DATE)
    VALUES (N'IND_EN_001', N'Responsable Man', N'Responsable Man', N'Piloter la performance énergétique du site industriel en optimisant les consommations, en garantissant la conformité à la norme ISO 50001 et en menant des projets d''efficacité énergétique pour réduire l''empreinte carbone et les coûts opérationnels de Sonasid.', NULL, N'<p>Définir et piloter la stratégie énergétique du site en cohérence avec les objectifs de la Direction Industrielle.</p><p>Assurer la mise en œuvre, le maintien et l&#x27;amélioration continue du Système de Management de l&#x27;Énergie (ISO 50001).</p><p>Analyser quotidiennement les consommations d&#x27;énergie (électricité, gaz, eau) et identifier les gisements d&#x27;économie.</p><p>Piloter les audits énergétiques périodiques et assurer le suivi des plans d&#x27;actions correctifs.</p><p>Concevoir et déployer des projets d&#x27;investissement (CAPEX) liés à l&#x27;efficacité énergétique.</p><p>Élaborer les reportings mensuels de performance énergétique et analyser les écarts par rapport au budget.</p><p>Sensibiliser et former les équipes opérationnelles aux éco-gestes et à l&#x27;optimisation des procédés thermiques.</p><p>Collaborer avec les achats pour optimiser les contrats de fourniture d&#x27;énergie.</p>', N'PRO', N'I', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, N'Évolution possible vers un poste de Responsable Maintenance, Responsable Excellence Opérationnelle ou Responsable Industriel de Site.', 0, GETDATE(), N'IMPORT_FDP', N'IMPORT_FDP', GETDATE(), GETDATE());
END;
